{"path": "book_store.py", "content": "from collections import Counter
from functools import lru_cache
from itertools import combinations

BOOK_PRICE = 800  # cents
DISCOUNTS = {1: 0, 2: 5, 3: 10, 4: 20, 5: 25}


def _group_price(size):
    return size * BOOK_PRICE * (100 - DISCOUNTS[size]) // 100


@lru_cache(maxsize=None)
def _best(counts):
    """Cheapest price in cents for a sorted tuple of per-title counts."""
    counts = tuple(c for c in counts if c)
    if not counts:
        return 0
    best = None
    indices = range(len(counts))
    for size in range(1, len(counts) + 1):
        for chosen in combinations(indices, size):
            rest = list(counts)
            for i in chosen:
                rest[i] -= 1
            price = _group_price(size) + _best(tuple(sorted(rest, reverse=True)))
            if best is None or price < best:
                best = price
    return best


def total(basket):
    """Return the lowest possible price of the basket, in cents."""
    counts = sorted(Counter(basket).values(), reverse=True)
    return _best(tuple(counts))
